package frc.robot.util.pathfinding.util;

import com.pathplanner.lib.path.PathPlannerPath;
import com.pathplanner.lib.trajectory.PathPlannerTrajectoryState;

import edu.wpi.first.wpilibj2.command.Command;
import edu.wpi.first.wpilibj2.command.Commands;
import frc.robot.util.pathfinding.builders.GoingMerry;
import frc.robot.util.pathfinding.commands.PPRecoveryCommand;

import java.util.function.BiFunction;

//* Enum determining the type of path recovery followed in ShinFollowPathCommand
public enum RecoveryType {
    // No extra recovery mode
    NO_RECOVERY((path, state) -> Commands.none()),

    // Uses a modified drive-to-point command
    DRIVE_TO_POINT_RECOVERY((path, state) -> PPRecoveryCommand.generateCommand(path, state)),

    // Pathfinds to the desired state
    PATHFINDING_RECOVERY((path, state) -> GoingMerry.pathfindToPose(state.pose, path.getGlobalConstraints(), state.linearVelocity)),

    //Users can set up to three custom recovery types in case they dont like the previous three
    CUSTOM_RECOVERY_ONE((path, state) -> RecoveryType.getCustomOne().apply(path, state)),
    CUSTOM_RECOVERY_TWO((path, state) -> RecoveryType.getCustomTwo().apply(path, state)),
    CUSTOM_RECOVERY_THREE((path, state) -> RecoveryType.getCustomThree().apply(path, state));

    private static BiFunction<PathPlannerPath, PathPlannerTrajectoryState, Command> customCommandSupplierOne = (p, s) -> Commands.none();
    private static BiFunction<PathPlannerPath, PathPlannerTrajectoryState, Command> customCommandSupplierTwo = (p, s) -> Commands.none();
    private static BiFunction<PathPlannerPath, PathPlannerTrajectoryState, Command> customCommandSupplierThree = (p, s) -> Commands.none();

    public final BiFunction<PathPlannerPath, PathPlannerTrajectoryState, Command> recoveryCommandBuilder;

    RecoveryType(BiFunction<PathPlannerPath, PathPlannerTrajectoryState, Command> recoveryCommandBuilder) {
        this.recoveryCommandBuilder = recoveryCommandBuilder;
    }

    private static RecoveryType current = NO_RECOVERY;
    //Backup for ShinPathfindingCommand, since pathfinding recovery inside a pathfinding command is pretty redundant
    private static RecoveryType backup = NO_RECOVERY;

    public static RecoveryType getCurrentMode() {
        return current;
    }

    public static RecoveryType getBackupMode() {
        return backup;
    }

    public static void setCurrentMode(RecoveryType type) {
        current = type;
    }

    public static void setBackupMode(RecoveryType type) {
        backup = type != PATHFINDING_RECOVERY ? type : NO_RECOVERY;
    }

    // *CUSTOM RECOVERY COMMANDS

    public static BiFunction<PathPlannerPath, PathPlannerTrajectoryState, Command> getCustomOne() {
        return customCommandSupplierOne;
    }

    public static void setCustomOne(BiFunction<PathPlannerPath, PathPlannerTrajectoryState, Command> supplier) {
        customCommandSupplierOne = supplier;
    }

    public static BiFunction<PathPlannerPath, PathPlannerTrajectoryState, Command> getCustomTwo() {
        return customCommandSupplierTwo;
    }

    public static void setCustomTwo(BiFunction<PathPlannerPath, PathPlannerTrajectoryState, Command> supplier) {
        customCommandSupplierTwo = supplier;
    }

    public static BiFunction<PathPlannerPath, PathPlannerTrajectoryState, Command> getCustomThree() {
        return customCommandSupplierThree;
    }

    public static void setCustomThree(BiFunction<PathPlannerPath, PathPlannerTrajectoryState, Command> supplier) {
        customCommandSupplierThree = supplier;
    }
}

